draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  // drawing a lightbulb to represent an idea (273 is a number that could represent an idea or concept)
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();
  // the filament
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 20 + 10 * Math.sin(t));
  ctx.lineTo(W/2, H/2 + 20 + 10 * Math.sin(t));
  ctx.stroke();
  // the electricity
  ctx.beginPath();
  ctx.moveTo(W/2 - 20, H/2 - 10 + 10 * Math.cos(t));
  ctx.lineTo(W/2 + 20, H/2 - 10 + 10 * Math.cos(t));
  ctx.stroke();
  // the number 273
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('273', W/2, H/2 + 60);
  ctx.restore();
}
